"""Future project-local CI reserve gate; no workflow submission API."""
import json, hashlib, copy, sys, subprocess
sys.path.insert(0,'/workspace/work/gpc-2121-runtime/.agents/skills/continuous-development-cycle/scripts')
import budget, execution_lease_v2, yaml
from contracts import StrictLoader, digest

ROUTES = {'required_pr_validation','retained_windows_exe'}
def check(approval, ledger, expected_ledger, request, *, coord, source):
    budget.validate_ledger(ledger)
    if approval.get('state') != 'ROOT_OWNER_APPROVED':
        raise ValueError('approval pending')
    if ledger != expected_ledger or coord != request['expected_coord'] or source != request['expected_source']:
        raise ValueError('stale ledger/coord/source')
    stages = approval['stages']
    if hashlib.sha256(json.dumps(stages,sort_keys=True,separators=(',',':')).encode()).hexdigest() != approval['stages_sha256']:
        raise ValueError('approved stage binding digest mismatch')
    stage = stages.get(request['stage'])
    if not stage or not stage.get('sha') or request['candidate_sha'] != stage['sha']:
        raise ValueError('unknown/wrong stage SHA')
    route = request['route']
    if route not in ROUTES or route not in stage['routes']:
        raise ValueError('route not approved')
    bound = stage['routes'][route]
    if request['attempt_id'] != bound['attempt_id'] or request['operation_key'] != bound['operation_key']:
        raise ValueError('operation binding mismatch')
    ci = [e for e in ledger['events'] if e['type']=='reserve' and e['kind']=='ci_start']
    # Every reservation counts, including unknown outcomes and historical charges.
    if len(ci) >= 10:
        raise ValueError('aggregate CI ceiling reached')
    if any(e['operation_key']==request['operation_key'] or e['attempt_id']==request['attempt_id'] for e in ci):
        raise ValueError('duplicate/unknown effect: reconcile, never replay')
    keys = {x['operation_key'] for x in stage['routes'].values()}
    if sum(e['operation_key'] in keys for e in ci) >= 2:
        raise ValueError('per-stage ceiling reached')
    if approval['historical_ci_event_ids'] != [e['event_id'] for e in ci[:2]]:
        raise ValueError('historical baseline mismatch')
    return True

def prepare(host, approved_store, adapter_path, expected_ledger, request):
    """Fresh authenticated durable record -> strict adapter/parity -> reserve INTENT.

    Caller must use canonical apply_event plus real CAS/readback, then the actual
    approved route. This function never submits CI or implies a provider API.
    """
    revision, approval = approved_store.read()
    if not revision or approval.get('state') != 'ROOT_OWNER_APPROVED':
        raise ValueError('durable approval pending')
    b = adapter_path.read_bytes()
    if hashlib.sha256(b).hexdigest()!=approval['adapter_sha256']:
        raise ValueError('adapter bytes mismatch')
    result=subprocess.run([sys.executable,'-B',host.S+'/validate_adapter.py',str(adapter_path)],capture_output=True,timeout=30)
    if result.returncode: raise ValueError('strict adapter invalid')
    adapter=yaml.load(b.decode(),Loader=StrictLoader)
    if digest(adapter)!=approval['adapter_digest']:raise ValueError('adapter semantic mismatch')
    coord,ledger,lease=host.read();execution_lease_v2.validate(lease)
    done={r['grant_id'] for r in lease['submission_resolutions']}
    if lease['external_guard'] is not None or any(c['grant_id'] not in done for c in lease['submission_claims']):
        raise ValueError('guard/unresolved claims')
    # CI may be reserved by the exact held publisher before its guarded push.
    if lease['owner_id'] is not None and (lease['owner_id'],lease['generation'],lease['invocation']['invocation_id']) != tuple(request['publisher_identity']):
        raise ValueError('wrong publisher ownership')
    if adapter['orchestration']['budget']!=ledger['policy'] or adapter['ci']['max_full_runs_per_task_when_conserve']!=10:
        raise ValueError('policy parity/conserve mismatch')
    check(approval,ledger,expected_ledger,request,coord=coord,source=host.head(host.REF))
    if approved_store.read()[0]!=revision or host.head(host.COORD)!=coord or host.head(host.REF)!=request['expected_source']:
        raise ValueError('freshness moved before reserve')
    event=dict(type='reserve',event_id=request['event_id'],task_id=ledger['task_id'],wake_id=ledger['wake_ids'][-1],at_utc=host.now(),kind='ci_start',operation_key=request['operation_key'],attempt_id=request['attempt_id'],scope='gpc/stage/'+request['stage']+'/'+request['route'],cost=dict(tool_calls=1,tokens=None,elapsed_seconds=None),recovery_ref=None)
    decision=budget.decide(ledger,event)
    if not decision['allow_reservation'] or decision['already_recorded']:raise ValueError('canonical reservation denied/reconcile')
    return dict(event=event,expected_coord=coord,updated=budget.apply_event(ledger,event),approval_revision=revision,external_submit_allowed=False)

