"""Synthetic API-shape regression only; not actual QUALITY admission."""
import unittest,sys,hashlib,copy
from pathlib import Path
from types import SimpleNamespace
sys.path.insert(0,str(Path(__file__).parent))
import prospective_controls as m
class ReachedHeldParent(Exception):pass
class Store:
 ref='refs/heads/cdc/SYNTHETIC-stage-approval'
 def __init__(self,case='good'):
  self.case=case;report='SYNTHETIC NOT ACTUAL QUALITY'
  quality=dict(status='completed',actual_agent_id='/root/SYNTHETIC',disposition='ACCEPTED',report_sha256=hashlib.sha256(report.encode()).hexdigest())
  self.body=dict(quality=quality,full_verbatim_report=report,terminal_observation=dict(tool='collaboration.list_agents',agent_status='completed',actual_agent_id='/root/SYNTHETIC'))
  self.approval=dict(quality=copy.deepcopy(quality),quality_record_revision='a'*40,quality_record_digest=m.hash_obj(self.body))
  if case=='missing':self.body.pop('full_verbatim_report');self.approval['quality_record_digest']=m.hash_obj(self.body)
  if case=='wrong_report':self.body['full_verbatim_report']='tampered';self.approval['quality_record_digest']=m.hash_obj(self.body)
  if case=='wrong_digest':self.approval['quality_record_digest']='sha256:'+'f'*64
 def read(self):return 'b'*40,self.approval
 def read_revision(self,revision):
  if self.case=='outside_ancestry':raise ValueError('historical revision is not in authoritative document ancestry')
  return self.body # canonical documented return is DICT, never tuple
class Tests(unittest.TestCase):
 def run_boundary(self,case):
  store=Store(case)
  def stop(*args):raise ReachedHeldParent('immutable report verified; stop before actual owner admission')
  host=SimpleNamespace(bridge=SimpleNamespace(_load_session=stop))
  return m.prepare(host,None,store,None,None,dict(handle_root='SYNTHETIC',handle_id='SYNTHETIC'))
 def test_document_dict_reaches_next_boundary(self):
  with self.assertRaises(ReachedHeldParent):self.run_boundary('good')
 def test_missing_report_denied(self):
  with self.assertRaisesRegex(ValueError,'report hash mismatch'):self.run_boundary('missing')
 def test_wrong_report_denied(self):
  with self.assertRaisesRegex(ValueError,'report hash mismatch'):self.run_boundary('wrong_report')
 def test_wrong_digest_denied(self):
  with self.assertRaisesRegex(ValueError,'immutable quality record mismatch'):self.run_boundary('wrong_digest')
 def test_other_ref_revision_denied(self):
  with self.assertRaisesRegex(ValueError,'authoritative document ancestry'):self.run_boundary('outside_ancestry')
if __name__=='__main__':unittest.main(verbosity=2)

