"""Actual push_pilot Git boundary, temporary local bare Git ONLY.
Ownership verify is a synthetic test seam, not real admission/QUALITY evidence.
"""
import unittest,tempfile,subprocess,os,sys,copy
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch
sys.path.insert(0,str(Path(__file__).parent));import prospective_controls as m
if '--original-caller' in sys.argv:
 sys.argv.remove('--original-caller')
 import importlib.util
 spec=importlib.util.spec_from_file_location('original_0086',Path(__file__).with_name('prospective_controls-0086-immutable.py'));m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
from git_remote_identity import endpoint_identity
E=os.environ.copy();E.update(GIT_NO_REPLACE_OBJECTS='1',GIT_GRAFT_FILE=os.devnull,GIT_AUTHOR_NAME='Synthetic CAS race',GIT_AUTHOR_EMAIL='test@example.invalid',GIT_COMMITTER_NAME='Synthetic CAS race',GIT_COMMITTER_EMAIL='test@example.invalid')
class Tests(unittest.TestCase):
 def case(self,competitor=None,lost_reply=False):
  with tempfile.TemporaryDirectory(prefix='gpc-pilot-absent-cas-') as td:
   root=Path(td);remote=root/'remote.git';local=root/'local'
   def run(args):return subprocess.run(args,env=E,capture_output=True)
   assert run(['git','init','--bare','-q',str(remote)]).returncode==0
   assert run(['git','init','-q',str(local)]).returncode==0
   def git(*args,check=True):
    r=run(['git','-C',str(local),*args]);
    if check and r.returncode:raise RuntimeError(r.stderr.decode())
    return r
   git('remote','add','origin',str(remote));(local/'f').write_text('ancestor');git('add','f');git('commit','-qm','ancestor');ancestor=git('rev-parse','HEAD').stdout.decode().strip()
   (local/'f').write_text('candidate');git('commit','-qam','candidate');candidate=git('rev-parse','HEAD').stdout.decode().strip()
   git('checkout','--detach',ancestor);(local/'f').write_text('sibling');git('commit','-qam','sibling');sibling=git('rev-parse','HEAD').stdout.decode().strip()
   source='refs/heads/design/SYNTHETIC';pilot='refs/heads/pilot/SYNTHETIC';git('push','origin',ancestor+':'+source)
   race={'done':False,'before':None,'push_exit':None,'push_stdout':None,'argv':None}
   def head(ref):
    data=git('ls-remote','--refs','origin',ref).stdout.split();observed=data[0].decode() if data else None
    if ref==pilot and not race['done']:
     race['done']=True
     if competitor:
      oid={'ancestor':ancestor,'sibling':sibling,'same':candidate}[competitor]
      git('push','origin',oid+':'+pilot);race['before']=oid
      print('competing '+competitor+' installed AFTER absent read '+oid)
    return observed
   def hostgit(*args,check=True):
    r=git(*args,check=check)
    if 'push' in args:
     race.update(push_exit=r.returncode,push_stdout=r.stdout.decode(),argv=list(args))
     if lost_reply and r.returncode==0:r.returncode=1;r.stderr=b'SYNTHETIC lost successful reply'
    return r
   host=SimpleNamespace(REPO=str(local),ID=endpoint_identity(str(remote)),REF=source,git=hostgit,head=head)
   effect=dict(intent=dict(operation_key='sha256:'+'a'*64,binding=dict(mode='retained_windows_exe',candidate_sha=candidate)))
   approval=dict(candidate_sha=candidate,pilot_ref=pilot);session=dict(plan=dict(base_sha=ancestor));directory=root/'journal'
   with patch.object(m,'verify_submission',lambda *args:None):
    if competitor or lost_reply:
     with self.assertRaisesRegex(ValueError,'conflict/unknown'):m.push_pilot(host,None,session,effect,approval,directory)
    else:self.assertEqual(m.push_pilot(host,None,session,effect,approval,directory)['readback'],candidate)
   final=git('ls-remote','--refs','origin',pilot).stdout.split()[0].decode()
   print('actual Git boundary '+str(competitor)+' exit='+str(race['push_exit'])+' stdout='+str(race['push_stdout'])+' final='+final)
   self.assertEqual(final,race['before'] if competitor else candidate,'Existing target MUST remain untouched even ancestor race')
   self.assertTrue(list(directory.glob('*.send-once')),'consumed intent retained')
   if lost_reply:
    # Lost-successful reply NEVER automatically sends again; existing send marker
    # and immutable target deny a second physical effect.
    with patch.object(m,'verify_submission',lambda *args:None):
     with self.assertRaises(ValueError):m.push_pilot(host,None,session,effect,approval,directory)
    self.assertEqual(git('ls-remote','--refs','origin',pilot).stdout.split()[0].decode(),candidate)
 def test_absent_success(self):self.case()
 def test_competing_ancestor_unchanged(self):self.case('ancestor')
 def test_competing_sibling_unchanged(self):self.case('sibling')
 def test_competing_same_candidate_unchanged_no_success_claim(self):self.case('same')
 def test_lost_successful_reply_observe_only(self):self.case(lost_reply=True)
if __name__=='__main__':unittest.main(verbosity=2)

