"""Prospective observed checkout gate; never equate PR source and merge SHA."""
import re
SHA=re.compile(r'^[0-9a-f]{40}$')
def check(e,*,candidate_sha,candidate_tree):
    for field in ('source_head_sha','tested_checkout_sha','tested_checkout_tree','github_sha','run_head_sha'):
        if not isinstance(e.get(field),str) or not SHA.fullmatch(e[field]):raise ValueError('missing observed '+field)
