    if not e.get('checkout_log_evidence_ref') or not e.get('git_object_evidence_ref'):raise ValueError('tested checkout identity is unproven')
    if e['tested_checkout_sha']!=e['github_sha']:raise ValueError('pinned default checkout differs from observed GitHub context')
    # run_head_sha is recorded independently. Do not use it as checkout proof.
    if e['route']=='retained_windows_exe':
        if e.get('event')!='push' or e['tested_checkout_sha']!=candidate_sha or e['tested_checkout_tree']!=candidate_tree or not e.get('ref','').startswith('refs/heads/pilot/'):raise ValueError('push EXE must build exact immutable candidate')
        if e.get('pilot_manifest_git_sha')!=candidate_sha:raise ValueError('pilot package source identity mismatch')
        return dict(validation_scope='exact_candidate_executable',source_sha=candidate_sha,tested_sha=e['tested_checkout_sha'],tested_tree=e['tested_checkout_tree'],candidate_tree_equal=True,run_head_sha=e['run_head_sha'])
    if e['route']=='required_pr_validation':
        if e.get('event')!='pull_request' or not isinstance(e.get('pr_number'),int):raise ValueError('required PR event missing')
        for field in ('pr_base_sha','pr_merge_sha'):
            if not isinstance(e.get(field),str) or not SHA.fullmatch(e[field]):raise ValueError('missing observed '+field)
        if e['tested_checkout_sha']!=e['pr_merge_sha'] or e.get('merge_parents')!=[e['pr_base_sha'],candidate_sha]:raise ValueError('actual tested PR merge/base/parents mismatch')
        if e.get('pr_base_sha')!=e.get('bound_base_sha'):raise ValueError('PR base changed: reconcile before accepting evidence')
        equal=e['tested_checkout_tree']==candidate_tree
        return dict(validation_scope='PR_integration_merge_checkout',source_sha=candidate_sha,tested_sha=e['tested_checkout_sha'],tested_tree=e['tested_checkout_tree'],base_sha=e['pr_base_sha'],merge_sha=e['pr_merge_sha'],candidate_tree_equal=equal,exact_candidate_commit_tested=False,run_head_sha=e['run_head_sha'])
    raise ValueError('unsupported CI route')

def authenticate_git_objects(host,e,*,candidate_sha):
    """Local genuine Git after bounded authenticated fetch of actual tested commit.
    Collect exact parents/tree; no source checkout/ref change or inferred merge.
    """
    tested=e['tested_checkout_sha'];tree=host.git('rev-parse',tested+'^{tree}').stdout.decode().strip()
    if tree!=e['tested_checkout_tree']:raise ValueError('observed checkout tree differs from genuine Git object')
    candidate_tree=host.git('rev-parse',candidate_sha+'^{tree}').stdout.decode().strip()
    if e['route']=='required_pr_validation':
        actual=host.git('show','-s','--format=%P',tested).stdout.decode().strip().split()
        if actual!=e['merge_parents']:raise ValueError('genuine tested merge parent mismatch')
    return check(e,candidate_sha=candidate_sha,candidate_tree=candidate_tree)

