    # Reuse strict validator/parity and canonical budget.decide/apply_event from reviewed CI helper.
    stages={a['stage']:dict(sha=a['candidate_sha'],routes=a['routes'])}
    bridge_approval={**a,'stages':stages,'stages_sha256':hashlib.sha256(json.dumps(stages,sort_keys=True,separators=(',',':')).encode()).hexdigest()}
    class ExactApproval:
        def read(self):
            actual,body=approval_store.read()
            if actual!=ar or body!=a:raise ValueError('approval moved')
            return actual,bridge_approval
    prepared=ci.prepare(host,ExactApproval(),adapter_path,expected_ledger,r)
    if journal_store.read()[0]!=jr:raise ValueError('journal moved during CI preparation')
    return {**prepared,'stage_approval_revision':ar,'intent':operation(a,r['route']),'approved':a}

def reserve_and_claim(host,prepared,intent_store,lease_store,session):
    """FUTURE normal real CAS route. Do not call before Root admits this draft.
    Persist intent, exact CI reservation/readback, then guard and one-shot claim.
    """
    r,ledger,lease=host.read()
    if r!=prepared['expected_coord']:raise ValueError('stale before CI reservation')
    # Full projection equality prevents replacing history from a template.
    if budget.apply_event(ledger,prepared['event'])!=prepared['updated']:raise ValueError('full fresh CI projection changed')
    dr,old=intent_store.read()
    if old is not None:raise ValueError('existing intent: reconcile, never reserve/replay')
    i=prepared['intent'];dr=intent_store.compare_and_swap(dr,i);actual,readback=intent_store.read()
    if actual!=dr or readback!=i:raise ValueError('intent readback mismatch')
    receipt=op.verify_readback(i,readback,'git:'+intent_store.ref+'@'+dr,host.now())
    host.ledger_cas(r,ledger,prepared['updated'],'combined-ci-'+prepared['event']['attempt_id'])
    _,current,_=host.read()
    if current!=prepared['updated']:raise ValueError('current complete reserved ledger differs')
    i=op.transition(i,'submitting',host.now(),receipt=receipt);dr=intent_store.compare_and_swap(dr,i)
    r,lease=lease_store.read()
    if host.head(host.REF)!=session['plan']['base_sha']:raise ValueError('source moved before guard')
    u=lv.set_guard(lease,session['owner_id'],session['generation'],session['invocation_id'],host.now(),i,'git:'+intent_store.ref+'@'+dr)
    r=lease_store.compare_and_swap(r,u)
    grant=lv.claim_submission(lease_store,r,session['lease_repository'],host.REF,session['owner_id'],session['generation'],session['invocation_id'],host.now(),intent_digest=op._hash(i))
    return dict(intent=i,intent_revision=dr,grant=grant,reserved_ledger=current)

def verify_submission(host,lease_store,session,effect):
    r,l=lease_store.read();lv.validate(l)
    i=effect['intent'];g=effect['grant']['grant'];guard=l['external_guard']
    runtime=host.bridge._runtime(session);observed=runtime.observe(session['task_id'],session['attempt_id'])
    if observed['status']!='running' or observed['quiescent']:raise ValueError('publisher parent is no longer genuinely live')
    candidate,_,_=host.bridge._result(session,runtime)
    if candidate!=i['binding']['candidate_sha']:raise ValueError('frozen candidate moved before effect')
    if (l['owner_id'],l['generation'],l['invocation']['invocation_id'])!=(session['owner_id'],session['generation'],session['invocation_id']):raise ValueError('ownership moved')
    # No invented second grant/check API. Match actual consumed canonical claim.
    if not guard or guard['intent']!=i or guard['submission_claim']!=g or g not in l['submission_claims'] or g['grant_id'] in lv._resolved_grant_ids(l):raise ValueError('exact unresolved consumed claim missing')
    at=op._timestamp(host.now(),'now')
    if l['finalization']['state']!='active' or at>=op._timestamp(l['expires_at_utc'],'expiry') or (at-op._timestamp(l['heartbeat_at_utc'],'heartbeat')).total_seconds()>=600:raise ValueError('ownership not fresh active')
    cr,ledger,_=host.read()
    if cr!=r or ledger!=effect['reserved_ledger'] or host.head(host.REF)!=session['plan']['base_sha']:raise ValueError('exact source/coord/reservation moved')
    return r

def push_pilot(host,lease_store,session,effect,approval,journal_directory):
    """FUTURE exact immutable pilot create; normal non-force Git only.
    Local durable single-send marker adds no authority. Unknown => observe only.
    """
    verify_submission(host,lease_store,session,effect)
    if effect['intent']['binding']['mode']!='retained_windows_exe' or effect['intent']['binding']['candidate_sha']!=approval['candidate_sha']:raise ValueError('wrong artifact intent')
    ref=approval['pilot_ref'];candidate=approval['candidate_sha']
    if not ref.startswith('refs/heads/pilot/') or host.head(ref) is not None:raise ValueError('immutable target exists: reconcile, never update')
    directory=Path(journal_directory);directory.mkdir(parents=True,exist_ok=True)
    path=directory/(effect['intent']['operation_key'].replace(':','-')+'.send-once')
    with path.open('x') as f:f.write(json.dumps(effect,sort_keys=True));f.flush();os.fsync(f.fileno())
    fd=os.open(directory,os.O_DIRECTORY);os.fsync(fd);os.close(fd)
    verify_submission(host,lease_store,session,effect)
    config,end=isolated_remote_args(host.REPO,'origin',host.ID)
    result=host.git(*config,'-c','push.followTags=false','push','--porcelain',end,candidate+':'+ref,check=False)
    observed=host.head(ref)
    if result.returncode or '[new branch]' not in result.stdout.decode() or observed!=candidate or host.head(host.REF)!=session['plan']['base_sha']:raise ValueError('publication conflict/unknown: preserve intent and guard, no replay')
    return dict(candidate_sha=candidate,ref=ref,expected_old_oid='0'*40,conditional_update=True,readback=observed,exit_code=result.returncode)

def pr_payload(a,r,prior_submission=False):
    if prior_submission:raise ValueError('prior/unknown PR submit: bounded search_prs and exact get_pr_info only; never replay')
    if r.get('route')!='required_pr_validation' or a['stage']!='0.17.1':raise ValueError('only0171 temporarydraftPR; laterstages use primaryPR92 synchronize viafinish')
    i=operation(a,r['route'])
    if (r['attempt_id'],r['operation_key'])!=(i['attempt_id'],i['operation_key']):raise ValueError('wrong PR intent binding')
    return dict(repository_full_name=REPO,head=a['pilot_ref'].removeprefix('refs/heads/'),base='main',draft=True,maintainer_can_modify=False,title='G PC Health '+a['stage']+' exact-SHA validation',body='Exact immutable candidate '+a['candidate_sha']+'. Required test validation only; no merge/release/Windows11 acceptance. This branch stays immutable.')

def prepare_pr_connector(host,lease_store,session,effect,approval,r,journal_directory):
    verify_submission(host,lease_store,session,effect)
    if host.head(approval['pilot_ref'])!=approval['candidate_sha']:raise ValueError('pilot source differs')
    if effect['intent']['binding']['mode']!='required_pr_validation' or effect['intent']['operation_key']!=r['operation_key']:raise ValueError('wrong PR guarded operation')
    args=pr_payload(approval,r)
    directory=Path(journal_directory);directory.mkdir(parents=True,exist_ok=True)
    with (directory/(r['operation_key'].replace(':','-')+'.connector-send-once')).open('x') as f:f.write(json.dumps(args,sort_keys=True));f.flush();os.fsync(f.fileno())
    fd=os.open(directory,os.O_DIRECTORY);os.fsync(fd);os.close(fd)
    verify_submission(host,lease_store,session,effect)
    return dict(tool='mcp__codex_apps__github_create_pull_request',arguments=args,grant_id=effect['grant']['grant']['grant_id'],one_shot=True)
    # Root calls the ACTUAL available connector once; no invented Python API.
    # Persist normalized reply+get_pr_info exacthead/draft/base/main readback.
    # Lost reply => actual github_search_prs exactrepo/head/allstate; don't recreate.


def reconcile_effect(host,intent_store,lease_store,session,effect,task):
    """Call ONLY after actual authoritative Git/PR readback of exact task.
    Terminal op is route-submission success, not terminal Windows CI success.
    """
    i=effect['intent']
    if task['operation_key']!=i['operation_key'] or task['binding']!=i['binding'] or task['attempt_id']!=i['attempt_id']:raise ValueError('wrong observed effect')
    revision,old=intent_store.read()
    if old!=i:raise ValueError('intent moved: reconcile')
    terminal=op.transition(i,'terminal',host.now(),task=task);revision=intent_store.compare_and_swap(revision,terminal)
    if intent_store.read()!=(revision,terminal):raise ValueError('terminal readback mismatch')
    observation=dict(schema='operation-observation/v1',operation_key=i['operation_key'],lookup_complete=True,observed_at_utc=host.now(),tasks=[task])
    if op.decide(terminal,observation)['action']!='reuse_terminal':raise ValueError('terminal reconciliation incomplete')
    r,l=lease_store.read();u=lv.clear_guard(l,session['owner_id'],session['generation'],session['invocation_id'],host.now(),observation,task['evidence_refs'][0]);r=lease_store.compare_and_swap(r,u)
    if lease_store.read()!=(r,u):raise ValueError('guard clear readback mismatch')
    return dict(intent_revision=revision,lease_revision=r,guard_resolved=True,CI_outcome_still_pending=True)


def reserve_primary_PR_for_finish(host,prepared,intent_store,session):
    """Future stage0172/018/019 primaryPR route: no PR create/dispatch.
    Persist the exact CI reservation while held; actual source update is ONLY
    canonical bridge.finish's durable conditional publisher. A generic external
    guard here would block its product_write gate, so never fabricate that route.
    """
    if prepared['approved']['stage']=='0.17.1' or prepared['event']['kind']!='ci_start' or prepared['intent']['binding']['mode']!='required_pr_validation':raise ValueError('wrong primaryPR route')
    r,ledger,lease=host.read()
    if r!=prepared['expected_coord'] or host.head(host.REF)!=session['plan']['base_sha']:raise ValueError('source/coord moved')
    if lease['external_guard'] is not None or (lease['owner_id'],lease['generation'],lease['invocation']['invocation_id'])!=(session['owner_id'],session['generation'],session['invocation_id']):raise ValueError('held exact publisher/no guard required')
    if budget.apply_event(ledger,prepared['event'])!=prepared['updated']:raise ValueError('complete fresh budget projection mismatch')
    dr,old=intent_store.read()
    if old is not None:raise ValueError('existing primaryPRintent: reconcile')
    dr=intent_store.compare_and_swap(dr,prepared['intent'])
    if intent_store.read()!=(dr,prepared['intent']):raise ValueError('primaryPRintent readback mismatch')
    rev=host.ledger_cas(r,ledger,prepared['updated'],'primaryPR-before-finish-'+prepared['event']['attempt_id'])
    cr,current,_=host.read()
    if cr!=rev or current!=prepared['updated']:raise ValueError('current complete reserved ledger differs')
    return dict(coordination=cr,intent_revision=dr,reservation_event=prepared['event'],CI_submit_method='only canonical managed_host_bridge.finish conditional sourcepublication; existing PR92 synchronize',CI_submitted=False,external_guard_created=False,requires_actual_publication_journal_readback=True)

